style.css:
body {
    background-color: #121212; /* Dark background */
    color: #ffffff; /* White text */
    font-family: 'Poppins', sans-serif; /* Clean modern font */
}

h1, h2, h3 {
    color: #00ffff; /* Neon cyan for headers */
    text-shadow: 0px 0px 10px #00ffff;
}

a {
    color: #ff007f; /* Neon pink links */
    text-decoration: none;
}

a:hover {
    color: #ff00ff;
    text-shadow: 0px 0px 10px #ff00ff;
}

button {
    background: linear-gradient(45deg, #00ffff, #ff007f);
    color: white;
    border: none;
    padding: 10px 20px;
    font-size: 16px;
    cursor: pointer;
    transition: all 0.3s ease;
}

button:hover {
    transform: scale(1.1);
    box-shadow: 0px 0px 15px #00ffff;
}
